"""Walkthrough wording copied from the original recruit dashboard."""

TEXT_0 = "## ⚔️ **Help me attack this base!**"

TEXT_1 = "Having doubts or concerns on a base you're going to attack? You have a few choices...\n\n**1)** Take a screenshot of the Base you wish to get info on. \nUse Find This Base <:FTB:1397098130792775781> `/scan` and add the pic into the command.\n\n**2)** Bring a screenshot here and ping the\n<@&1006460305464905808>\nRole for one-on-one help.\n\n**3)** Bring a screenshot here and ping the Town Hall Role equal to the Base you're attacking.\n\nFor those joining FWA, the above will be helpful in Mismatch Wars and Blacklisted Wars."

TEXT_2 = "## 🎉 **Welcome to the Team!**"

TEXT_3 = "This is your Lounge... All of our Clans chill and converse here. Feel free to post anything you'd like here but we ask to keep your War related stuff in your Clan's War Channels.\n\nYou may have noticed we changed your nickname to match your CoC name. Makes it easier for everyone to know who they're talking to.\n\nAs we're an International Family, we've added your Timezone acronym at the tail end of your nickname. It helps us know where everyone is in the World.\n\nWelcome to Warriors United!! Feel free to ask questions regarding anything about the operation. Pinging our Leaders is acceptable. We're here to help...🫡"

TEXT_4 = '## 😈 **Welcome to Warriors United "noob"**'

TEXT_5 = "We have a special way of welcoming noobs into the Fam...."

TEXT_6 = "## 🎯 **How to request troops!**"

TEXT_7 = "If you need troops for War or any other urgent reason, come here and use this slash command format with 🧙 Clash Commander Bot...\n\n`/announce donate`\nor\n`/announce supertroop`\n\nThen simply enter the message you'd like to send to the donor as well as the troop name.\n\nIt pings the person(s) in the clan who can provide Max Level for requested troops...👍🏻\n\nIf you're wanting a Friendly Challenge(FC) and no one of your level is online in-game, this is where you would send for a FC. It doesn't always get them to come in game but it's your best bet to get their attention...💪🏼\n\nSimply ping the TH Level Role in your Clan's Chat Channel and all players with that Level in your Clan will be announced."
